/**
 * Backs the admin "record finder" Lightning component.
 *
 * Builds one SOQL query from validated object/field names and bind variables
 * for all filter values. The query runs in USER_MODE so the running user's
 * record sharing and field-level security are enforced by the platform.
 */
public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    private static final Integer MIN_ROWS = 1;
    private static final Integer MAX_ROWS = 200;

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name is required.');
        }
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }
        if (maxRows == null || maxRows < MIN_ROWS || maxRows > MAX_ROWS) {
            throw new SearchException('maxRows must be between ' + MIN_ROWS + ' and ' + MAX_ROWS + '.');
        }

        // Object lookup is case-insensitive (keys of getGlobalDescribe are lowercase).
        Schema.SObjectType sot = Schema.getGlobalDescribe().get(objectApiName.trim().toLowerCase());
        if (sot == null) {
            throw new SearchException('Unknown object: ' + objectApiName);
        }
        Schema.DescribeSObjectResult dso = sot.getDescribe();
        if (!dso.isAccessible()) {
            throw new SearchException('You do not have read access to object: ' + dso.getName());
        }
        Map<String, Schema.SObjectField> fieldMap = dso.fields.getMap();

        // ---- SELECT list ----
        List<String> selectFields = new List<String>{ 'Id' };
        Set<String> seen = new Set<String>{ 'id' };
        for (String f : fields) {
            Schema.DescribeFieldResult fd = describeField(fieldMap, f, dso.getName());
            String canonical = fd.getName();
            if (seen.add(canonical.toLowerCase())) {
                selectFields.add(canonical);
            }
        }

        // ---- WHERE clause (values are bound, never concatenated) ----
        Map<String, Object> binds = new Map<String, Object>();
        List<String> conditions = new List<String>();
        if (filters != null && !filters.isEmpty()) {
            Integer idx = 0;
            for (String key : filters.keySet()) {
                Schema.DescribeFieldResult fd = describeField(fieldMap, key, dso.getName());
                if (!fd.isFilterable()) {
                    throw new SearchException('Field cannot be filtered: ' + fd.getName());
                }
                String bindName = 'f' + idx;
                idx++;
                binds.put(bindName, coerce(fd, filters.get(key)));
                conditions.add(fd.getName() + ' = :' + bindName);
            }
        }

        // ---- ORDER BY ----
        String orderClause = '';
        if (!String.isBlank(orderByField)) {
            Schema.DescribeFieldResult fd = describeField(fieldMap, orderByField, dso.getName());
            if (!fd.isSortable()) {
                throw new SearchException('Field cannot be sorted: ' + fd.getName());
            }
            orderClause = ' ORDER BY ' + fd.getName() + ' ASC';
        }

        binds.put('lim', maxRows);

        String query = 'SELECT ' + String.join(selectFields, ', ')
            + ' FROM ' + dso.getName()
            + (conditions.isEmpty() ? '' : ' WHERE ' + String.join(conditions, ' AND '))
            + orderClause
            + ' LIMIT :lim';

        try {
            return Database.queryWithBinds(query, binds, System.AccessLevel.USER_MODE);
        } catch (QueryException e) {
            throw new SearchException('Search failed: ' + e.getMessage());
        }
    }

    /**
     * Resolves a field name case-insensitively and verifies it exists and is readable
     * by the running user (field-level security).
     */
    private static Schema.DescribeFieldResult describeField(
        Map<String, Schema.SObjectField> fieldMap,
        String name,
        String objectName
    ) {
        if (String.isBlank(name)) {
            throw new SearchException('Blank field name supplied for object: ' + objectName);
        }
        Schema.SObjectField sf = fieldMap.get(name.trim().toLowerCase());
        if (sf == null) {
            throw new SearchException('Field ' + name + ' does not exist on object ' + objectName);
        }
        Schema.DescribeFieldResult fd = sf.getDescribe();
        if (!fd.isAccessible()) {
            throw new SearchException('You do not have read access to field: ' + fd.getName());
        }
        return fd;
    }

    /**
     * Converts a UI-supplied value into a type that matches the field so it can be
     * bound safely. Any conversion problem is reported as a SearchException.
     */
    private static Object coerce(Schema.DescribeFieldResult fd, Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof List<Object> || value instanceof Map<String, Object> || value instanceof SObject) {
            throw new SearchException('Unsupported filter value for field: ' + fd.getName());
        }

        Schema.DisplayType t = fd.getType();
        try {
            if (t == Schema.DisplayType.BOOLEAN) {
                if (value instanceof Boolean) {
                    return value;
                }
                String s = String.valueOf(value).trim().toLowerCase();
                if (s == 'true') return true;
                if (s == 'false') return false;
                throw new SearchException('Invalid boolean value for field: ' + fd.getName());
            }

            if (t == Schema.DisplayType.DATE) {
                if (value instanceof Date) {
                    return value;
                }
                return Date.valueOf(String.valueOf(value).trim());
            }

            if (t == Schema.DisplayType.DATETIME) {
                if (value instanceof Datetime) {
                    return value;
                }
                return Datetime.valueOf(String.valueOf(value).trim());
            }

            if (t == Schema.DisplayType.INTEGER) {
                if (value instanceof Integer) {
                    return value;
                }
                Decimal d = Decimal.valueOf(String.valueOf(value).trim());
                if (d != d.setScale(0)) {
                    throw new SearchException('Invalid integer value for field: ' + fd.getName());
                }
                return d.intValue();
            }

            if (t == Schema.DisplayType.DOUBLE
                || t == Schema.DisplayType.CURRENCY
                || t == Schema.DisplayType.PERCENT) {
                if (value instanceof Decimal) {
                    return value;
                }
                return Decimal.valueOf(String.valueOf(value).trim());
            }

            if (t == Schema.DisplayType.ID || t == Schema.DisplayType.REFERENCE) {
                if (value instanceof Id) {
                    return value;
                }
                return Id.valueOf(String.valueOf(value).trim());
            }

            // Text-like types (String, Picklist, Email, Phone, URL, TextArea, ...)
            return String.valueOf(value);
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            throw new SearchException('Invalid value for field ' + fd.getName() + ': ' + e.getMessage());
        }
    }
}
