/**
 * Flow-invocable action that finds an existing Contact by email address.
 *
 * - Runs in the running user's sharing context (with sharing).
 * - Bulkified: one SOQL query per invocation, regardless of request count.
 * - Matching is case-insensitive and ignores leading/trailing whitespace.
 * - When several contacts share an email, the earliest CreatedDate wins
 *   (Id is used as a deterministic tie-breaker).
 * - Returns exactly one Result per Request, in the same order as the input.
 */
public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(label='Email' description='Email address to search for' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact ID' description='Id of the matching contact, or null')
        public Id contactId;

        @InvocableVariable(label='Found' description='True when a matching contact was found')
        public Boolean found = false;
    }

    @InvocableMethod(label='Find Contact by Email' description='Finds the earliest-created contact with the given email address (case-insensitive).')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // 1. Collect distinct normalized search keys across the whole batch.
        Set<String> searchKeys = new Set<String>();
        for (Request req : requests) {
            String key = normalize(req == null ? null : req.email);
            if (key != null) {
                searchKeys.add(key);
            }
        }

        // 2. Single query for the whole batch. Ordering ensures the first
        //    contact encountered per email is the earliest created one.
        Map<String, Id> contactIdByEmail = new Map<String, Id>();
        if (!searchKeys.isEmpty()) {
            for (Contact c : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :searchKeys
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                String key = normalize(c.Email);
                if (key != null && !contactIdByEmail.containsKey(key)) {
                    contactIdByEmail.put(key, c.Id);
                }
            }
        }

        // 3. Build one result per request, preserving input order.
        for (Request req : requests) {
            Result res = new Result();
            res.found = false;
            res.contactId = null;

            String key = normalize(req == null ? null : req.email);
            if (key != null && contactIdByEmail.containsKey(key)) {
                res.contactId = contactIdByEmail.get(key);
                res.found = true;
            }
            results.add(res);
        }

        return results;
    }

    /**
     * Trims and lower-cases an email. Returns null for null or blank input.
     */
    private static String normalize(String value) {
        if (value == null) {
            return null;
        }
        String trimmed = value.trim();
        return String.isBlank(trimmed) ? null : trimmed.toLowerCase();
    }
