@IsTest
private class AddressVerificationServiceTest {

    private static final String ENDPOINT = 'callout:FB_Address_API/v2/verify';

    /** Records every callout and returns a canned response. */
    private class MockHttp implements HttpCalloutMock {
        private Integer statusCode;
        private String responseBody;
        public Integer callCount = 0;
        public HttpRequest lastRequest;

        public MockHttp(Integer statusCode, String responseBody) {
            this.statusCode = statusCode;
            this.responseBody = responseBody;
        }

        public HttpResponse respond(HttpRequest req) {
            callCount++;
            lastRequest = req;
            HttpResponse res = new HttpResponse();
            res.setStatusCode(statusCode);
            res.setHeader('Content-Type', 'application/json');
            res.setBody(responseBody);
            return res;
        }
    }

    private static Account buildAccount() {
        return new Account(
            Name = 'Address Test Account',
            BillingStreet = '1 Original Street',
            BillingCity = 'Oldtown',
            BillingPostalCode = '11111',
            BillingCountry = 'Germany'
        );
    }

    private static String addressBody(String status, String street, String city, String postal, String country) {
        return JSON.serialize(new Map<String, Object>{
            'status' => status,
            'address' => new Map<String, Object>{
                'street' => street,
                'city' => city,
                'postalCode' => postal,
                'country' => country
            }
        });
    }

    @IsTest
    static void blankStreetIsSkippedWithoutCallout() {
        Account acct = buildAccount();
        acct.BillingStreet = null;
        MockHttp mock = new MockHttp(200, addressBody('VERIFIED', 'x', 'x', 'x', 'x'));
        Test.setMock(HttpCalloutMock.class, mock);

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals('SKIPPED', result.status, 'Blank street should be SKIPPED');
        System.assertEquals(false, result.changed);
        System.assertEquals(0, mock.callCount, 'No callout should be made for a blank street');
    }

    @IsTest
    static void whitespaceOnlyStreetIsSkippedWithoutCallout() {
        Account acct = buildAccount();
        acct.BillingStreet = '   ';
        MockHttp mock = new MockHttp(200, addressBody('VERIFIED', 'x', 'x', 'x', 'x'));
        Test.setMock(HttpCalloutMock.class, mock);

