public with sharing class LeadImportService {

    public class ImportResult {
        public Integer successCount = 0;
        public List<Id> insertedIds = new List<Id>();
        public Map<Integer, String> errorsByIndex = new Map<Integer, String>();
    }

    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();
        if (leads == null || leads.isEmpty()) {
            return result;
        }

        List<Lead> toInsert = new List<Lead>();
        Set<String> seenEmails = new Set<String>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead l = leads[i];
            if (l == null) {
                result.errorsByIndex.put(i, 'Lead record is null');
                continue;
            }

            String email = normaliseEmail(l.Email);
            if (email != null) {
                if (seenEmails.contains(email)) {
                    result.errorsByIndex.put(i, 'Duplicate email in import: ' + email);
                    continue;
                }
                seenEmails.add(email);
            }

            if (String.isBlank(l.LeadSource)) {
                l.LeadSource = 'Web';
            }

            toInsert.add(l);
        }

        if (toInsert.isEmpty()) {
            return result;
        }

        // Map each insert candidate back to its original input position.
        // Build the index list in the same pass order as toInsert.
        List<Integer> inputIndexes = new List<Integer>();
        Integer cursor = 0;
        for (Integer i = 0; i < leads.size(); i++) {
            Lead l = leads[i];
            if (l == null) {
                continue;
            }
            if (result.errorsByIndex.containsKey(i)) {
                continue;
            }
            inputIndexes.add(i);
            cursor++;
        }

        // Single DML statement; partial success allowed; respects user sharing and FLS/CRUD.
        List<Database.SaveResult> saveResults =
            Database.insert(toInsert, false, AccessLevel.USER_MODE);

        for (Integer j = 0; j < saveResults.size(); j++) {
            Database.SaveResult sr = saveResults[j];
            Integer originalIndex = inputIndexes[j];
            if (sr.isSuccess()) {
                result.successCount++;
                result.insertedIds.add(sr.getId());
            } else {
                List<String> messages = new List<String>();
                for (Database.Error err : sr.getErrors()) {
                    messages.add(err.getMessage());
                }
                result.errorsByIndex.put(originalIndex, String.join(messages, '; '));
            }
        }

        return result;
    }

    private static String normaliseEmail(String email) {
        if (email == null) {
            return null;
        }
        String trimmed = email.trim().toLowerCase();
        return String.isBlank(trimmed) ? null : trimmed;
    }
}
