public with sharing class PicklistService {

    /**
     * One active picklist value. value = API value, label = display label,
     * isDefault = true only when this is the field's default value.
     */
    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {}

    /**
     * Returns the active values of a picklist or multi-select picklist field,
     * in the order they are defined on the field. Object and field API names
     * are case-insensitive and may be standard or custom.
     *
     * @throws PicklistServiceException when a name is blank, the object or field
     *         does not exist, or the field is not a picklist / multi-select picklist.
     */
    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Object and field API names are required.');
        }

        String objName = objectApiName.trim().toLowerCase();
        String fieldName = fieldApiName.trim().toLowerCase();

        Schema.SObjectType sObjType = Schema.getGlobalDescribe().get(objName);
        if (sObjType == null) {
            throw new PicklistServiceException('Object does not exist: ' + objectApiName);
        }

        Map<String, Schema.SObjectField> fieldMap = sObjType.getDescribe().fields.getMap();
        Schema.SObjectField sObjField = fieldMap.get(fieldName);
        if (sObjField == null) {
            throw new PicklistServiceException('Field ' + fieldApiName + ' does not exist on object ' + objectApiName);
        }

        Schema.DescribeFieldResult dfr = sObjField.getDescribe();
        Schema.DisplayType displayType = dfr.getType();
        if (displayType != Schema.DisplayType.PICKLIST && displayType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException('Field ' + fieldApiName + ' on ' + objectApiName
                + ' is not a picklist or multi-select picklist.');
        }

        List<Option> options = new List<Option>();
        for (Schema.PicklistEntry entry : dfr.getPicklistValues()) {
            if (entry.isActive()) {
                options.add(new Option(entry.getValue(), entry.getLabel(), entry.isDefaultValue()));
            }
        }
        return options;
    }
}
