public with sharing class ErpSyncFinalizer implements Finalizer {

    public static final String JOB_NAME = 'ErpAccountSyncJob';
    public static final Integer MAX_ATTEMPTS = 3;
    private static final Integer MAX_ERROR_LENGTH = 255;

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : accountIds.clone();
        this.attempt = attempt;
    }

    public void execute(FinalizerContext ctx) {
        Boolean succeeded = ctx.getResult() == ParentJobResult.SUCCESS;

        FB_Job_Log__c log = new FB_Job_Log__c(
            Job_Name__c = JOB_NAME,
            Attempt__c = attempt
        );

        if (succeeded) {
            log.Status__c = 'Success';
        } else {
            log.Status__c = 'Failed';
            log.Error__c = truncate(ctx.getException() == null ? null : ctx.getException().getMessage());
        }

        insert log;

        if (!succeeded && attempt < MAX_ATTEMPTS) {
            System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
        }
    }

    private static String truncate(String value) {
        if (value == null) {
