/**
 * Keeps Account.FB_Open_Pipeline__c and Account.FB_Open_Opportunities__c in sync
 * with the account's open (IsClosed = false) opportunities.
 *
 * Design:
 * - Totals are always recomputed from the database with one aggregate query, so the
 *   result is correct regardless of how many DML statements touched the records
 *   earlier in the transaction (no reliance on deltas or stale trigger data).
 * - Accounts are only updated when a stored value actually changes. This makes the
 *   recalculation idempotent and guarantees termination when AccountTrigger (which
 *   updates opportunities) and this handler re-enter each other.
 * - Bulk safe: one aggregate query, one account query, one update DML per invocation.
 */
public without sharing class OpportunityPipelineHandler {

    /**
     * @param newOpps  Trigger.new for insert/update/undelete, null for delete
     * @param oldOpps  Trigger.old for update/delete, null for insert/undelete
     */
    public static void recalculate(List<Opportunity> newOpps, List<Opportunity> oldOpps) {
        Set<Id> accountIds = new Set<Id>();

        if (oldOpps == null) {
            // insert / undelete
            collectFromInserted(newOpps, accountIds);
        } else if (newOpps == null) {
            // delete
            for (Opportunity o : oldOpps) {
                addIfPresent(accountIds, o.AccountId);
            }
        } else {
            // update
            Map<Id, Opportunity> oldById = new Map<Id, Opportunity>(oldOpps);
            for (Opportunity o : newOpps) {
                Opportunity prev = oldById.get(o.Id);
                if (prev == null) {
                    addIfPresent(accountIds, o.AccountId);
                    continue;
                }
                Boolean accountChanged = prev.AccountId != o.AccountId;
                Boolean stageChanged = prev.IsClosed != o.IsClosed;
                Boolean amountChanged = prev.Amount != o.Amount;
                if (accountChanged || stageChanged || amountChanged) {
                    // Both the old and the new account must be refreshed when an opportunity moves.
                    addIfPresent(accountIds, prev.AccountId);
                    addIfPresent(accountIds, o.AccountId);
                }
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }
        refreshAccounts(accountIds);
    }

    private static void collectFromInserted(List<Opportunity> opps, Set<Id> accountIds) {
        for (Opportunity o : opps) {
            addIfPresent(accountIds, o.AccountId);
        }
    }

    private static void addIfPresent(Set<Id> ids, Id accountId) {
        if (accountId != null) {
            ids.add(accountId);
        }
    }

    private static void refreshAccounts(Set<Id> accountIds) {
        // Aggregate open pipeline per account. Accounts with no open opportunities
        // produce no row and are treated as 0 / 0 below.
        Map<Id, Decimal> pipelineByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> countByAccount = new Map<Id, Integer>();

        for (AggregateResult ar : [
            SELECT AccountId accId, COUNT(Id) cnt, SUM(Amount) amt
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('accId');
            Integer cnt = Integer.valueOf(ar.get('cnt'));
            Decimal amt = (Decimal) ar.get('amt');
            pipelineByAccount.put(accId, amt == null ? 0 : amt);
            countByAccount.put(accId, cnt == null ? 0 : cnt);
        }

        List<Account> toUpdate = new List<Account>();
        for (Account acc : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Decimal expectedPipeline = pipelineByAccount.containsKey(acc.Id)
                ? pipelineByAccount.get(acc.Id)
                : 0;
            Integer expectedCount = countByAccount.containsKey(acc.Id)
                ? countByAccount.get(acc.Id)
                : 0;

            Boolean pipelineDiffers = acc.FB_Open_Pipeline__c == null
                || acc.FB_Open_Pipeline__c != expectedPipeline;
            Boolean countDiffers = acc.FB_Open_Opportunities__c == null
                || acc.FB_Open_Opportunities__c != expectedCount;

            if (pipelineDiffers || countDiffers) {
                acc.FB_Open_Pipeline__c = expectedPipeline;
                acc.FB_Open_Opportunities__c = expectedCount;
                toUpdate.add(acc);
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
