/**
 * Nightly purge of FB_Integration_Log__c records.
 *
 * Retention rules:
 *  - Non-ERROR logs (DEBUG, INFO, blank Level__c, etc.) are deleted once created more than 30 days ago.
 *  - ERROR logs are kept until created more than 180 days ago.
 *
 * The schedulable entry point hands the work to a batch class so that large
 * volumes are processed in chunks within governor limits.
 *
 * Runs in system context (without sharing) so that every log is purged regardless
 * of the running user's sharing or record visibility.
 */
public without sharing class LogPurgeJob implements Schedulable {

    public static final String JOB_NAME = 'Log purge (nightly)';
    public static final String CRON_EXPRESSION = '0 0 2 * * ?';
    public static final Integer NON_ERROR_RETENTION_DAYS = 30;
    public static final Integer ERROR_RETENTION_DAYS = 180;
    public static final Integer BATCH_SIZE = 2000;

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext sc) {
        Database.executeBatch(new PurgeBatch(), BATCH_SIZE);
    }

    /**
     * Schedules the purge to run every day at 02:00 under JOB_NAME.
     * Any previously scheduled job with the same name is aborted first so that
     * re-running setup does not fail on duplicate job names.
     */
    public static Id scheduleNightly() {
        for (CronTrigger ct : [
            SELECT Id
            FROM CronTrigger
            WHERE CronJobDetail.Name = :JOB_NAME
        ]) {
            System.abortJob(ct.Id);
        }
        return System.schedule(JOB_NAME, CRON_EXPRESSION, new LogPurgeJob());
    }

    /**
     * Batch that performs the actual deletion. Declared as a nested class so the
     * purge logic stays inside LogPurgeJob.
     */
    public without sharing class PurgeBatch implements Database.Batchable<SObject> {

        public Database.QueryLocator start(Database.BatchableContext bc) {
            Datetime nonErrorCutoff = Datetime.now().addDays(-NON_ERROR_RETENTION_DAYS);
            Datetime errorCutoff = Datetime.now().addDays(-ERROR_RETENTION_DAYS);

            // Note: Level__c != 'ERROR' alone excludes blank (null) levels in SOQL,
            // so the null check is included explicitly.
            return Database.getQueryLocator([
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE (CreatedDate < :nonErrorCutoff
                        AND (Level__c = null OR Level__c != 'ERROR'))
                   OR (CreatedDate < :errorCutoff
                        AND Level__c = 'ERROR')
            ]);
        }

        public void execute(Database.BatchableContext bc, List<FB_Integration_Log__c> scope) {
            if (scope == null || scope.isEmpty()) {
                return;
            }
            // Partial success allowed so one locked/undeletable record does not
            // roll back the whole chunk; failures are logged to the debug log.
            List<Database.DeleteResult> results = Database.delete(scope, false);
            for (Integer i = 0; i < results.size(); i++) {
                if (!results[i].isSuccess()) {
                    for (Database.Error err : results[i].getErrors()) {
                        System.debug(LoggingLevel.ERROR,
                            'LogPurgeJob failed to delete ' + scope[i].Id + ': '
                            + err.getStatusCode() + ' - ' + err.getMessage());
                    }
                }
            }
        }

        public void finish(Database.BatchableContext bc) {
            // No post-processing required.
        }
    }
}
