/**
 * Computes closed-won revenue per account for the current calendar year.
 *
 * - Sums Opportunity.Amount for IsWon = true opportunities whose CloseDate is in
 *   the current calendar year (SOQL literal THIS_YEAR, evaluated in the running
 *   user's time zone).
 * - Performs the aggregation in the database with a single SUM / GROUP BY query.
 * - Runs in user mode with "with sharing" so the running user's record sharing
 *   and field-level security are respected.
 * - Every requested (non-null) account Id is a key in the result; accounts with
 *   no qualifying opportunities, or only blank amounts, map to 0.
 */
public with sharing class OpportunityRollupService {

    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Copy the requested ids, dropping nulls, so that only real requested
        // Ids become keys and the bind set is clean.
        Set<Id> requestedIds = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                requestedIds.add(accountId);
            }
        }

        if (requestedIds.isEmpty()) {
            return result;
        }

        // Every requested account defaults to 0 (never null).
        for (Id accountId : requestedIds) {
            result.put(accountId, 0);
        }

        List<AggregateResult> rows = [
            SELECT AccountId accId, SUM(Amount) total
            FROM Opportunity
            WHERE AccountId IN :requestedIds
              AND IsWon = true
              AND CloseDate = THIS_YEAR
            GROUP BY AccountId
            WITH USER_MODE
        ];

        for (AggregateResult row : rows) {
            Id accountId = (Id) row.get('accId');
            Decimal total = (Decimal) row.get('total');

            // SUM returns null when every qualifying Amount is blank.
            if (accountId != null && total != null) {
                result.put(accountId, total);
            }
        }

        return result;
    }
}
