        mocks.stopStubbing();

        Map<String, Decimal> totals = OpportunityForecastService.weightedAmountByStage(accountIds);

        System.assertEquals(6.66, totals.get('Prospecting'), 'Each opportunity must be rounded to 2 decimals before summing');
