    public static final String DEFAULT_TYPE = 'New Customer';
    public static final Integer DEFAULT_CLOSE_DATE_OFFSET_DAYS = 30;

    public Opportunities(List<Opportunity> records) {
        super(records);
    }

    public override void onBeforeInsert() {
        applyCreationDefaults((List<Opportunity>) Records);
    }

    /**
     * Applies default values to Opportunities being created.
     * Only blank fields are populated; values already set are preserved.
     * Runs on insert only, so updates are never altered by these defaults.
     */
    private static void applyCreationDefaults(List<Opportunity> opps) {
        Date defaultCloseDate = Date.today().addDays(DEFAULT_CLOSE_DATE_OFFSET_DAYS);
        for (Opportunity opp : opps) {
            if (opp.CloseDate == null) {
                opp.CloseDate = defaultCloseDate;
            }
            if (String.isBlank(opp.Type)) {
                opp.Type = DEFAULT_TYPE;
            }
        }
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }
}
