public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    private static final String CREDIT_REVIEW_FIELD_SET = 'Credit_Review';

    public AccountsSelector() {
        // Data access (USER_MODE => WITH USER_MODE) is set here so that every query
        // from this selector is enforced against the running user's permissions.
        // Field set fields are added explicitly below, so includeFieldSetFields is false.
        super(false, fflib_SObjectSelector.DataAccess.USER_MODE);
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        Map<String, Schema.SObjectField> fieldsByName = new Map<String, Schema.SObjectField>();

        addField(fieldsByName, Account.Id);
        addField(fieldsByName, Account.Name);
        addField(fieldsByName, Account.Industry);

        // Pull the Credit_Review field set at runtime so admins can change it without code changes.
        Schema.FieldSet creditReviewFieldSet =
            Schema.SObjectType.Account.fieldSets.getMap().get(CREDIT_REVIEW_FIELD_SET);

        if (creditReviewFieldSet != null) {
            Map<String, Schema.SObjectField> accountFieldMap =
                Schema.SObjectType.Account.fields.getMap();

            for (Schema.FieldSetMember member : creditReviewFieldSet.getFields()) {
                Schema.SObjectField field = accountFieldMap.get(member.getFieldPath().toLowerCase());
                if (field != null) {
                    addField(fieldsByName, field);
                }
            }
        }

        return fieldsByName.values();
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        List<String> accountFieldNames = toFieldNames(getSObjectFieldList());
        List<String> contactFieldNames = toFieldNames(new ContactsSelector().getSObjectFieldList());

        String soql =
            'SELECT ' + String.join(accountFieldNames, ', ') +
            ', (SELECT ' + String.join(contactFieldNames, ', ') + ' FROM Contacts)' +
            ' FROM Account' +
            ' WHERE Id IN :accountIds' +
            ' WITH USER_MODE';

        return (List<Account>) Database.query(soql);
    }

    private static void addField(Map<String, Schema.SObjectField> fieldsByName, Schema.SObjectField field) {
        fieldsByName.put(field.getDescribe().getName().toLowerCase(), field);
    }

    private static List<String> toFieldNames(List<Schema.SObjectField> fields) {
        List<String> names = new List<String>();
        for (Schema.SObjectField field : fields) {
            names.add(field.getDescribe().getName());
        }
        return names;
    }
}
