public with sharing class LineItemDiscountHandler {

    /**
     * Sets the standard discount on new opportunity lines where the rep
     * did not enter a Discount. Lines with a Discount (including 0) are unchanged.
     * Bulkified: one Product2 query per batch, regardless of line count.
     */
    public static void applyStandardDiscounts(List<OpportunityLineItem> lines) {
        Set<Id> productIds = new Set<Id>();
        for (OpportunityLineItem line : lines) {
            if (line.Discount == null && line.Product2Id != null) {
                productIds.add(line.Product2Id);
            }
        }
        if (productIds.isEmpty()) {
            return;
        }

        Map<Id, String> familyByProduct = new Map<Id, String>();
        for (Product2 product : [
            SELECT Id, Family
            FROM Product2
            WHERE Id IN :productIds
        ]) {
            familyByProduct.put(product.Id, product.Family);
        }

        for (OpportunityLineItem line : lines) {
            if (line.Discount == null && familyByProduct.containsKey(line.Product2Id)) {
                line.Discount = PricingRules.standardDiscountForFamily(
                    familyByProduct.get(line.Product2Id)
                );
            }
        }
    }
}
