public with sharing class CaseSurveyJob implements Queueable {

    private final Set<Id> caseIds;

    public CaseSurveyJob(Set<Id> caseIds) {
        this.caseIds = caseIds.clone();
    }

    public void execute(QueueableContext context) {
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        // Re-query to get CaseNumber and to confirm the case is still closed and has a contact.
        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :caseIds
              AND IsClosed = true
              AND ContactId != null
        ];

        if (cases.isEmpty()) {
            return;
        }

        Date surveyDate = Date.today().addDays(2);
        List<Task> tasks = new List<Task>();
        List<Id> taskCaseIds = new List<Id>();

        for (Case c : cases) {
            tasks.add(new Task(
                WhatId = c.Id,
                WhoId = c.ContactId,
                Subject = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = surveyDate,
                Status = 'Not Started'
            ));
            taskCaseIds.add(c.Id);
        }

        // allOrNone = false: a failing Task does not prevent the others from being created.
        Database.SaveResult[] results = Database.insert(tasks, false);

        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                for (Database.Error err : results[i].getErrors()) {
                    System.debug(LoggingLevel.ERROR,
                        'CaseSurveyJob: failed to create survey task for Case ' +
                        taskCaseIds[i] + ': ' + err.getStatusCode() + ' - ' + err.getMessage());
                }
            }
        }
    }
}
