/**
 * Sends renewal reminder emails to the owners of the given Opportunities.
 *
 * Messages are built in memory and sent in chunks of up to 100 per
 * Messaging.sendEmail invocation (with allOrNone = false), so:
 *  - a 200-record batch uses 2 send invocations, well under the 10-per-transaction limit;
 *  - a failure for one recipient does not stop the others.
 */
public with sharing class RenewalReminderService {

    private static final Integer MAX_MESSAGES_PER_SEND = 100;

    /**
     * @param opportunityIds Opportunity Ids whose renewal is due (expected up to 200).
     * @return The number of emails that were accepted for sending successfully.
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ];

        List<Messaging.SingleEmailMessage> messages = new List<Messaging.SingleEmailMessage>();
        for (Opportunity opp : opportunities) {
            messages.add(buildMessage(opp));
        }

        Integer sentCount = 0;
        Integer total = messages.size();

        for (Integer start = 0; start < total; start += MAX_MESSAGES_PER_SEND) {
            Integer finish = Math.min(start + MAX_MESSAGES_PER_SEND, total);
            List<Messaging.SingleEmailMessage> chunk = new List<Messaging.SingleEmailMessage>();
            for (Integer i = start; i < finish; i++) {
                chunk.add(messages[i]);
            }

            // allOrNone = false: each message succeeds or fails independently.
            List<Messaging.SendEmailResult> results = Messaging.sendEmail(chunk, false);
            for (Messaging.SendEmailResult result : results) {
                if (result.isSuccess()) {
                    sentCount++;
                }
            }
        }

        return sentCount;
    }

    private static Messaging.SingleEmailMessage buildMessage(Opportunity opp) {
        String closeDateText = (opp.CloseDate == null)
            ? 'not set'
            : opp.CloseDate.format();

        Messaging.SingleEmailMessage message = new Messaging.SingleEmailMessage();
        message.setTargetObjectId(opp.OwnerId);
        message.setSaveAsActivity(false);
        message.setSubject('Renewal due: ' + opp.Name);
        message.setPlainTextBody(
            'Hello,\n\n' +
            'The renewal for your opportunity "' + opp.Name + '" is due. ' +
            'The opportunity close date is ' + closeDateText + '.\n\n' +
            'Please review the opportunity and take any needed action.'
        );
        return message;
    }
}
```

