import { LightningElement, api, wire } from 'lwc';
import { getRecord } from 'lightning/uiRecordApi';

const ACCOUNT_FIELDS = [
    'Account.Name',
    'Account.Industry',
    'Account.AnnualRevenue',
    'Account.Owner.Name'
];

export default class AccountHeader extends LightningElement {
    @api recordId;

    // '$recordId' makes the wire reactive: changing recordId (e.g. a reused console tab)
    // makes the adapter fetch the new record.
    @wire(getRecord, { recordId: '$recordId', fields: ACCOUNT_FIELDS })
    account;

    get hasData() {
        return !!this.account?.data && !this.account?.error;
    }

    get hasError() {
        return !!this.account?.error;
    }

    get isLoading() {
        return !this.account?.data && !this.account?.error;
    }

    get name() {
        return this.account?.data?.fields?.Name?.value;
    }

    get industry() {
        return this.account?.data?.fields?.Industry?.value;
    }

    get hasIndustry() {
        const value = this.industry;
        return value !== null && value !== undefined && value !== '';
