import { LightningElement, api } from 'lwc';

const THEME_BY_STATUS = {
    New: 'slds-theme_info',
    Escalated: 'slds-theme_error',
    Closed: 'slds-theme_success'
};

export default class CaseStatusBadge extends LightningElement {
    /** Case status text to display. Set by the parent component. */
    @api status;

    /** True when status holds a non-blank value. */
    get hasStatus() {
        return this.status !== null && this.status !== undefined && String(this.status).trim() !== '';
    }

    /** Base badge class plus a theme class for known statuses only. */
    get badgeClass() {
        const key = this.hasStatus ? String(this.status) : '';
        const theme = Object.prototype.hasOwnProperty.call(THEME_BY_STATUS, key)
            ? THEME_BY_STATUS[key]
            : null;
        return theme ? `slds-badge ${theme}` : 'slds-badge';
    }
}
