import { LightningElement, api } from 'lwc';

/**
 * Presentational list of an account's contacts.
 * Data is supplied by the parent; this component performs no fetching.
 */
export default class AccountContactList extends LightningElement {
    /**
     * Array of { Id, Name, Title } objects. Title is optional.
     * The parent owns this array; it is never mutated here.
     * Reassigning the property with a new array triggers a re-render.
     */
    @api contacts;

    /** Normalised, read-only view of the input (guards undefined, null and non-arrays). */
    get _contacts() {
        return Array.isArray(this.contacts) ? this.contacts : [];
    }

    get isEmpty() {
        return this._contacts.length === 0;
    }

    get countText() {
        const count = this._contacts.length;
        return count === 1 ? '1 contact' : `${count} contacts`;
    }

    /**
     * Copy before sorting so the parent's array is left untouched.
     * Sorted by Name ascending using localeCompare.
     */
    get sortedContacts() {
        return [...this._contacts]
            .sort((a, b) => (a.Name || '').localeCompare(b.Name || ''))
            .map((contact) => ({
                Id: contact.Id,
                Name: contact.Name,
                Title: contact.Title,
                hasTitle: !!contact.Title
            }));
    }
}
