```javascript
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_MS = 300;
const MIN_TERM_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    contacts = [];
    errorMessage;

    _debounceTimer;
    _latestRequestId = 0;
    _isConnected = false;

    connectedCallback() {
        this._isConnected = true;
    }

    disconnectedCallback() {
        this._isConnected = false;
        this._clearDebounceTimer();
        // Invalidate any in-flight request so its response is ignored.
        this._latestRequestId++;
    }

    get hasResults() {
        return this.contacts.length > 0;
    }

    handleSearchChange(event) {
        const term = (event.target.value || '').trim();

        // Every keystroke cancels the previously scheduled search.
        this._clearDebounceTimer();

        if (term.length < MIN_TERM_LENGTH) {
            // Invalidate in-flight requests and reset the view; no Apex call.
            this._latestRequestId++;
            this.contacts = [];
            this.errorMessage = undefined;
            return;
        }

        this._debounceTimer = setTimeout(() => {
            this._debounceTimer = undefined;
            this._runSearch(term);
        }, DEBOUNCE_MS);
    }

    _runSearch(term) {
        if (!this._isConnected) {
            return;
        }

        const requestId = ++this._latestRequestId;

        searchContacts({ searchTerm: term })
            .then((result) => {
                if (!this._isStale(requestId)) {
                    this.contacts = result || [];
                    this.errorMessage = undefined;
                }
            })
            .catch((error) => {
                if (!this._isStale(requestId)) {
                    this.contacts = [];
                    this.errorMessage =
                        (error && error.body && error.body.message) ||
                        'An unexpected error occurred while searching.';
                }
            });
    }

    _isStale(requestId) {
        return !this._isConnected || requestId !== this._latestRequestId;
    }

    _clearDebounceTimer() {
        if (this._debounceTimer !== undefined) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = undefined;
        }
    }
}
