import { LightningElement, api, wire } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import { updateRecord } from 'lightning/uiRecordApi';
import { refreshApex } from '@salesforce/apex';
import getContacts from '@salesforce/apex/ContactController.getContacts';

const COLUMNS = [
    { label: 'Name', fieldName: 'Name', type: 'text', editable: false },
    { label: 'Title', fieldName: 'Title', type: 'text', editable: true },
    { label: 'Phone', fieldName: 'Phone', type: 'phone', editable: true },
    { label: 'Email', fieldName: 'Email', type: 'email', editable: true }
];

export default class AccountContactsTable extends LightningElement {
    @api recordId;

    columns = COLUMNS;
    contacts = [];
    draftValues = [];
    wiredContactsResult;
    loadError;

    @wire(getContacts, { accountId: '$recordId' })
    wiredContacts(result) {
        this.wiredContactsResult = result;
        const { data, error } = result;
        if (data) {
            this.contacts = data;
            this.loadError = undefined;
        } else if (error) {
            this.contacts = [];
            this.loadError = error;
        }
    }

    async handleSave(event) {
        const drafts = event.detail.draftValues || [];

        const updates = drafts.map((draft) =>
            updateRecord({ fields: { ...draft } })
        );

        // allSettled waits for every update to finish, so no request is left running
        const results = await Promise.allSettled(updates);
        const failures = results.filter((r) => r.status === 'rejected');

        if (failures.length === 0) {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Contacts updated',
                    variant: 'success'
                })
            );
            this.draftValues = [];
            await refreshApex(this.wiredContactsResult);
        } else {
            const reason = failures[0].reason;
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Could not save contacts',
                    message: reason?.body?.message,
                    variant: 'error'
                })
            );
        }
    }
}
