import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import { deleteRecord } from 'lightning/uiRecordApi';
import LightningConfirm from 'lightning/confirm';

const OPPORTUNITY_OBJECT = 'Opportunity';

const COLUMNS = [
    { label: 'Name', fieldName: 'Name', type: 'text' },
    { label: 'Stage', fieldName: 'StageName', type: 'text' },
    { label: 'Amount', fieldName: 'Amount', type: 'currency' },
    {
        type: 'action',
        typeAttributes: {
            rowActions: [
                { label: 'View', name: 'view' },
                { label: 'Edit', name: 'edit' },
                { label: 'Delete', name: 'delete' }
            ]
        }
    }
];

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    columns = COLUMNS;

    // Parent-supplied source data (never mutated by this component).
    _opportunities = [];

    // Internal copy used for display; rows are removed from this copy only.
    rows = [];

    @api
    get opportunities() {
        return this._opportunities;
    }
    set opportunities(value) {
        this._opportunities = value;
        // Build a fresh array so the parent's array is never modified.
        this.rows = Array.isArray(value) ? value.map((item) => ({ ...item })) : [];
    }

    handleRowAction(event) {
        const actionName = event.detail.action.name;
        const row = event.detail.row;

        switch (actionName) {
            case 'view':
                this.navigateToRecord(row.Id, 'view');
                break;
            case 'edit':
                this.navigateToRecord(row.Id, 'edit');
                break;
            case 'delete':
                this.confirmAndDelete(row);
                break;
            default:
                break;
        }
    }

    navigateToRecord(recordId, actionName) {
        this[NavigationMixin.Navigate]({
            type: 'standard__recordPage',
            attributes: {
                recordId,
                objectApiName: OPPORTUNITY_OBJECT,
                actionName
            }
        });
    }

    async confirmAndDelete(row) {
        let confirmed = false;
        try {
            confirmed = await LightningConfirm.open({
                message: `Are you sure you want to delete "${row.Name}"? This cannot be undone.`,
                variant: 'header',
                label: 'Delete Opportunity',
                theme: 'error'
            });
        } catch (error) {
            // Modal dismissed or failed to open: treat as cancel.
            return;
        }

        if (!confirmed) {
            return;
        }

        try {
            await deleteRecord(row.Id);
            this.rows = this.rows.filter((r) => r.Id !== row.Id);
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Opportunity deleted',
                    variant: 'success'
                })
            );
        } catch (error) {
            const message =
                (error && error.body && error.body.message) ||
                'An unexpected error occurred.';
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Delete failed',
                    message,
                    variant: 'error'
                })
            );
        }
    }
}
