import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const POLL_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    stats;
    errorMessage;

    _connected = false;
    _inFlight = false;
    _timerId = null;

    // Stable reference so the same function can be added and removed.
    _handleVisibilityChange = () => this.handleVisibilityChange();

    get waiting() {
        return this.stats ? this.stats.waiting : undefined;
    }

    get longestWaitMinutes() {
        return this.stats ? this.stats.longestWaitMinutes : undefined;
    }

    connectedCallback() {
        if (this._connected) {
            return;
        }
        this._connected = true;
        document.addEventListener('visibilitychange', this._handleVisibilityChange);

        // While hidden, make no requests; polling starts when the page becomes visible.
        if (document.visibilityState !== 'hidden') {
            this.startPolling();
        }
    }

    disconnectedCallback() {
        this._connected = false;
        document.removeEventListener('visibilitychange', this._handleVisibilityChange);
        this.stopPolling();
    }

    handleVisibilityChange() {
        if (!this._connected) {
            return;
        }
        if (document.visibilityState === 'hidden') {
            this.stopPolling();
        } else {
            this.startPolling();
        }
    }

    startPolling() {
        // Guarantees a single polling loop: always clear any existing timer first.
        this.stopPolling();
        this.refresh();
        this._timerId = setInterval(() => this.refresh(), POLL_INTERVAL_MS);
    }

    stopPolling() {
        if (this._timerId !== null) {
            clearInterval(this._timerId);
            this._timerId = null;
        }
    }

    async refresh() {
        if (!this._connected || this._inFlight || document.visibilityState === 'hidden') {
            return;
        }

        this._inFlight = true;
        try {
            const data = await getQueueStats();
            if (!this._connected) {
                return;
            }
            this.stats = {
                waiting: data.waiting,
                longestWaitMinutes: data.longestWaitMinutes
            };
            this.errorMessage = undefined;
        } catch (error) {
            if (this._connected) {
                this.errorMessage =
                    (error && error.body && error.body.message) ||
                    (error && error.message) ||
                    'Unable to load queue statistics.';
            }
        } finally {
            this._inFlight = false;
        }
    }
}
