import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const BLOCKED_EMAIL_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];
const PERSONAL_EMAIL_MESSAGE = 'Use your work email address.';

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleChange(event) {
        const field = event.target.dataset.field;
        const value = event.detail.value;

        switch (field) {
            case 'fullName':
                this.fullName = value;
                break;
            case 'email':
                this.email = value;
                break;
            case 'company':
                this.company = value;
                break;
            default:
                break;
        }
    }

    get inputs() {
        return Array.from(this.template.querySelectorAll('[data-field]'));
    }

    getEmailInput() {
        return this.template.querySelector('[data-field="email"]');
    }

    isBlockedEmailDomain(email) {
        const value = (email || '').trim();
        const atIndex = value.lastIndexOf('@');
        if (atIndex < 0) {
            return false;
        }
        const domain = value.substring(atIndex + 1).toLowerCase();
        return BLOCKED_EMAIL_DOMAINS.includes(domain);
    }

    applyEmailDomainRule() {
        const emailInput = this.getEmailInput();
        if (!emailInput) {
            return;
        }
        if (this.isBlockedEmailDomain(this.email)) {
            emailInput.setCustomValidity(PERSONAL_EMAIL_MESSAGE);
        } else {
            emailInput.setCustomValidity('');
        }
    }

    async handleRegister() {
        // Step 1: work email rule, applied before validity reporting.
        this.applyEmailDomainRule();

        // Step 2: report on every input without short-circuiting,
        // so all invalid fields show their messages at once.
        const results = this.inputs.map((input) => input.reportValidity());

        // Step 3: stop if any input is invalid.
        if (results.includes(false)) {
            return;
        }

        try {
            await register({
                fullName: this.fullName,
                email: this.email,
                company: this.company
            });

            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registered',
                    variant: 'success'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registration failed',
                    message: error.body.message,
                    variant: 'error'
                })
            );
        }
    }
}
