import { LightningElement, api } from 'lwc';

let instanceCounter = 0;

// Only these keys are handled (and only these call preventDefault).
const HANDLED_KEYS = new Set(['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' ']);

export default class StatusListbox extends LightningElement {
    _uid = `status-listbox-${++instanceCounter}`;
    _options = [];
    _value = '';
    _activeIndex = -1;

    /** Accessible name of the listbox. */
    @api label;

    /** Array of { value, label }. */
    @api
    get options() {
        return this._options;
    }
    set options(newOptions) {
        this._options = Array.isArray(newOptions) ? newOptions : [];
        this._activeIndex = this.resolveActiveIndex();
    }

    /** Selected value (may be empty). Parent may change it at any time. */
    @api
    get value() {
        return this._value;
    }
    set value(newValue) {
        this._value = newValue == null ? '' : newValue;
        this._activeIndex = this.resolveActiveIndex();
    }

    // ---- Derived state for the template ----

    get renderedOptions() {
        return this._options.map((opt, index) => {
            const isSelected = opt.value === this._value;
            const isActive = index === this._activeIndex;
            return {
                key: this.optionId(index),
                id: this.optionId(index),
                index,
                value: opt.value,
                label: opt.label,
                ariaSelected: isSelected ? 'true' : 'false',
                className: isActive
                    ? 'slds-listbox__option slds-has-focus'
                    : 'slds-listbox__option'
            };
        });
    }

    get activeDescendantId() {
        if (this._activeIndex >= 0 && this._activeIndex < this._options.length) {
            return this.optionId(this._activeIndex);
        }
        return undefined;
    }

    // ---- Event handlers ----

    handleKeyDown(event) {
        const key = event.key;
        if (!HANDLED_KEYS.has(key)) {
            return; // let every other key (e.g. Tab) keep its default behaviour
        }
        event.preventDefault();

        const lastIndex = this._options.length - 1;
        if (lastIndex < 0) {
            return;
        }

        switch (key) {
            case 'ArrowDown':
                this._activeIndex = Math.min(Math.max(this._activeIndex, 0) + 1, lastIndex);
                break;
            case 'ArrowUp':
                this._activeIndex = Math.max(this._activeIndex - 1, 0);
                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = lastIndex;
                break;
            case 'Enter':
            case ' ':
                this.selectIndex(this._activeIndex);
                break;
            default:
                break;
        }
    }

    handleClick(event) {
        const index = Number(event.currentTarget.dataset.index);
        if (!Number.isInteger(index) || index < 0 || index >= this._options.length) {
            return;
        }
        this._activeIndex = index;
        this.selectIndex(index);
    }

    // ---- Helpers ----

    selectIndex(index) {
        const option = this._options[index];
        if (!option) {
            return;
        }
        if (option.value === this._value) {
            return; // already selected: no change event
        }
        this._value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', { detail: { value: option.value } })
        );
    }

    indexOfValue(value) {
        return this._options.findIndex((opt) => opt.value === value);
    }

    /**
     * Active option is the selected option if there is one, otherwise the first option.
     */
    resolveActiveIndex() {
        const selectedIndex = this.indexOfValue(this._value);
        if (selectedIndex >= 0) {
            return selectedIndex;
        }
        return this._options.length > 0 ? 0 : -1;
    }

    optionId(index) {
        return `${this._uid}-option-${index}`;
    }
}
