```apex
/**
 * Sets the current primary employer (NPSP Affiliation) for each contact.
 *
 * Relies on NPSP's own affiliation trigger handling to:
 *   - clear the Primary flag on any previous primary affiliation,
 *   - mark that previous affiliation Former with an end date,
 *   - sync Contact.npsp__Primary_Affiliation__c.
 *
 * Bulk-safe: 2 SOQL queries and at most 2 DML statements, regardless of input size.
 */
public with sharing class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Keep only usable pairs.
        Map<Id, Id> wanted = new Map<Id, Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id orgId = employerByContactId.get(contactId);
            if (contactId != null && orgId != null) {
                wanted.put(contactId, orgId);
            }
        }
        if (wanted.isEmpty()) {
            return;
        }

        // SOQL 1: contacts and their current primary affiliation lookup.
        Map<Id, Contact> contactsById = new Map<Id, Contact>(
            [
                SELECT Id, npsp__Primary_Affiliation__c
                FROM Contact
                WHERE Id IN :wanted.keySet()
            ]
        );

        // SOQL 2: all affiliations for these contacts (any status).
        List<npe5__Affiliation__c> existingAffs = [
            SELECT Id, npe5__Contact__c, npe5__Organization__c,
                   npe5__Status__c, npe5__Primary__c, npe5__EndDate__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :wanted.keySet()
        ];

        // Index affiliations by contact+organization.
        Map<String, npe5__Affiliation__c> affByKey = new Map<String, npe5__Affiliation__c>();
        for (npe5__Affiliation__c aff : existingAffs) {
            String key = aff.npe5__Contact__c + '|' + aff.npe5__Organization__c;
            // Prefer an already-primary, current affiliation if several exist.
            npe5__Affiliation__c prior = affByKey.get(key);
            if (prior == null || isPrimaryCurrent(aff)) {
                affByKey.put(key, aff);
            }
        }

        List<npe5__Affiliation__c> toUpdate = new List<npe5__Affiliation__c>();
        List<npe5__Affiliation__c> toInsert = new List<npe5__Affiliation__c>();
        Date today = Date.today();

        for (Id contactId : wanted.keySet()) {
            Id orgId = wanted.get(contactId);
            Contact con = contactsById.get(contactId);
            if (con == null) {
                continue; // Contact not found or not visible to this user.
            }

            String key = contactId + '|' + orgId;
            npe5__Affiliation__c aff = affByKey.get(key);

            // Already correct: nothing to do.
            if (aff != null && isPrimaryCurrent(aff) && con.npsp__Primary_Affiliation__c == orgId) {
                continue;
            }

            if (aff != null) {
                // Existing affiliation to this org: promote it to primary/current.
                // NPSP demotes the previous primary and syncs the contact lookup.
                aff.npe5__Primary__c = true;
                aff.npe5__Status__c = 'Current';
                aff.npe5__EndDate__c = null;
                toUpdate.add(aff);
            } else {
                // New affiliation: NPSP demotes the previous primary to Former.
                toInsert.add(new npe5__Affiliation__c(
                    npe5__Contact__c = contactId,
                    npe5__Organization__c = orgId,
                    npe5__Primary__c = true,
                    npe5__Status__c = 'Current',
                    npe5__StartDate__c = today
                ));
            }
        }

        // DML 1: promote existing affiliations.
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
        // DML 2: insert new primary affiliations.
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    private static Boolean isPrimaryCurrent(npe5__Affiliation__c aff) {
        return aff.npe5__Primary__c == true && aff.npe5__Status__c == 'Current';
    }
}
