/**
 * Splits an opportunity's GAU allocations by percentage.
 *
 * Allocations are written as Percent only (Amount left blank). NPSP derives
 * npsp__Amount__c from the opportunity amount and recalculates it when the
 * opportunity amount changes, so a $1,000 gift at 60/40 becomes $1,200/$800
 * after the amount is corrected to $2,000 without further code.
 */
public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {
        // ---- Validation (no data is changed until everything passes) ----
        if (opportunityId == null) {
            throw new AllocationException('An opportunity Id is required.');
        }
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU percentage is required.');
        }

        List<Opportunity> opps = [
            SELECT Id
            FROM Opportunity
            WHERE Id = :opportunityId
            WITH USER_MODE
            LIMIT 1
        ];
        if (opps.isEmpty()) {
            throw new AllocationException('Opportunity not found or not accessible: ' + opportunityId);
        }

        Decimal total = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('GAU Id cannot be null.');
            }
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null || pct <= 0) {
                throw new AllocationException('Each percentage must be greater than 0. Invalid value for GAU ' + gauId + '.');
            }
            total += pct;
        }
        if (total > 100) {
            throw new AllocationException('Percentages total ' + total + '%, which exceeds 100%.');
        }

        Map<Id, npsp__General_Accounting_Unit__c> gaus = new Map<Id, npsp__General_Accounting_Unit__c>([
            SELECT Id, npsp__Active__c
            FROM npsp__General_Accounting_Unit__c
            WHERE Id IN :percentByGauId.keySet()
            WITH USER_MODE
        ]);
        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gaus.get(gauId);
            if (gau == null) {
                throw new AllocationException('GAU not found or not accessible: ' + gauId);
            }
            if (gau.npsp__Active__c != true) {
                throw new AllocationException('GAU is inactive and cannot be allocated: ' + gauId);
            }
        }

        // ---- Replace existing opportunity-level allocations ----
        List<npsp__Allocation__c> existing = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
            WITH USER_MODE
        ];
        if (!existing.isEmpty()) {
            delete existing;
        }

        // ---- Build and insert new percent-based allocations ----
        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            newAllocations.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
            ));
        }
        insert newAllocations;

        return newAllocations;
    }
}
