/**
 * Creates one NPSP Household Account for a family of new Contacts.
 *
 * Approach: NPSP's Contact trigger creates and names a Household Account
 * (record type HH_Account) when a Contact is inserted without an AccountId.
 * We insert only the primary contact without an AccountId so NPSP creates
 * exactly one household. The remaining members are inserted in one bulk DML
 * with that household's Id. Finally, the household's primary contact
 * (npe01__One2OneContact__c) is set. A savepoint rolls everything back on
 * failure, so no stray household is left behind.
 */
public with sharing class HouseholdService {

    private static final String HOUSEHOLD_RECORD_TYPE_DEV_NAME = 'HH_Account';

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must contain at least one Contact.');
        }

        Savepoint sp = Database.setSavepoint();
        try {
            // Step 1: insert the primary contact alone (no AccountId).
            // NPSP creates and names exactly one Household Account for it.
            Contact primary = members[0];
            primary.AccountId = null;
            insert primary;

            Id householdId = [
                SELECT AccountId
                FROM Contact
                WHERE Id = :primary.Id
                WITH SECURITY_ENFORCED
            ].AccountId;

            if (householdId == null) {
                throw new IllegalStateException('NPSP did not create a household for the primary contact.');
            }

            // Verify the account is an NPSP Household (HH_Account), not an Organization.
            Account household = [
                SELECT Id, RecordType.DeveloperName
                FROM Account
                WHERE Id = :householdId
                WITH SECURITY_ENFORCED
            ];
            if (household.RecordType == null || household.RecordType.DeveloperName != HOUSEHOLD_RECORD_TYPE_DEV_NAME) {
                throw new IllegalStateException('Account ' + householdId + ' is not an NPSP Household Account.');
            }

            // Step 2: insert the remaining members in one bulk DML against the same household.
            List<Contact> others = new List<Contact>();
            for (Integer i = 1; i < members.size(); i++) {
                Contact c = members[i];
                c.AccountId = householdId;
                others.add(c);
            }
            if (!others.isEmpty()) {
                insert others;
            }

            // Step 3: set the household's primary contact.
            update new Account(
                Id = householdId,
                npe01__One2OneContact__c = primary.Id
            );

            return householdId;
        } catch (Exception e) {
            Database.rollback(sp);
            throw e;
        }
    }
}
