/**
 * Records a received (Closed Won) gift for a contact in the NPSP Household Account model.
 *
 * NPSP may auto-create the primary contact role and a payment when an Opportunity is inserted
 * (depending on Contact Role and Payment settings). This class reconciles those automatic records
 * so that the gift ends with exactly one payment and exactly one contact role per contact.
 */
public with sharing class GiftService {

    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final String ROLE_DONOR = 'Donor';
    private static final String ROLE_HOUSEHOLD_MEMBER = 'Household Member';

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('contactId is required.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('amount must be a positive, non-null value.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('giftDate is required.');
        }

        List<Contact> donors = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (donors.isEmpty()) {
            throw new IllegalArgumentException('Contact not found: ' + contactId);
        }
        Contact donor = donors[0];
        if (donor.AccountId == null) {
            throw new IllegalArgumentException('Contact has no household account: ' + contactId);
        }

        String firstPart = String.isBlank(donor.FirstName) ? '' : donor.FirstName + ' ';
        String oppName = firstPart + donor.LastName + ' Donation ' + String.valueOf(giftDate);

        Opportunity opp = new Opportunity(
            Name = oppName,
            AccountId = donor.AccountId,
            Amount = amount,
            CloseDate = giftDate,
            StageName = STAGE_CLOSED_WON,
            npsp__Primary_Contact__c = donor.Id
        );
        insert opp;

        reconcilePayments(opp.Id, amount, giftDate);
        reconcileContactRoles(opp.Id, donor);

        return opp.Id;
    }

    /**
     * Ensures exactly one paid payment for the full amount, dated giftDate.
     * Reuses an NPSP auto-created payment if one exists; removes any extras.
     */
    private static void reconcilePayments(Id oppId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> existing = [
            SELECT Id
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :oppId
            ORDER BY Id
        ];

        if (existing.isEmpty()) {
            insert new npe01__OppPayment__c(
                npe01__Opportunity__c = oppId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
            return;
        }

        npe01__OppPayment__c keep = existing[0];
        List<npe01__OppPayment__c> extras = new List<npe01__OppPayment__c>();
        for (Integer i = 1; i < existing.size(); i++) {
            extras.add(existing[i]);
        }
        if (!extras.isEmpty()) {
            delete extras;
        }

        keep.npe01__Payment_Amount__c = amount;
        keep.npe01__Payment_Date__c = giftDate;
        keep.npe01__Scheduled_Date__c = giftDate;
        keep.npe01__Paid__c = true;
        update keep;
    }

    /**
     * Ensures the donor holds the Donor role (primary) and every other household member holds
     * the Household Member role, with no contact holding more than one role on the gift.
     * Roles for contacts outside the desired set are removed.
     */
    private static void reconcileContactRoles(Id oppId, Contact donor) {
        Map<Id, String> desiredRoles = new Map<Id, String>();
        desiredRoles.put(donor.Id, ROLE_DONOR);

        for (Contact member : [
            SELECT Id
            FROM Contact
            WHERE AccountId = :donor.AccountId
              AND Id != :donor.Id
        ]) {
            desiredRoles.put(member.Id, ROLE_HOUSEHOLD_MEMBER);
        }

        List<OpportunityContactRole> existing = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :oppId
            ORDER BY Id
        ];

        Map<Id, OpportunityContactRole> kept = new Map<Id, OpportunityContactRole>();
        List<OpportunityContactRole> toDelete = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toUpdate = new List<OpportunityContactRole>();

        for (OpportunityContactRole ocr : existing) {
            if (!desiredRoles.containsKey(ocr.ContactId) || kept.containsKey(ocr.ContactId)) {
                toDelete.add(ocr);
                continue;
            }
            kept.put(ocr.ContactId, ocr);
        }

        for (Id contactId : kept.keySet()) {
            OpportunityContactRole ocr = kept.get(contactId);
            String wantedRole = desiredRoles.get(contactId);
            Boolean wantedPrimary = (contactId == donor.Id);
            if (ocr.Role != wantedRole || ocr.IsPrimary != wantedPrimary) {
                ocr.Role = wantedRole;
                ocr.IsPrimary = wantedPrimary;
                toUpdate.add(ocr);
            }
        }

        List<OpportunityContactRole> toInsert = new List<OpportunityContactRole>();
        for (Id contactId : desiredRoles.keySet()) {
            if (!kept.containsKey(contactId)) {
                toInsert.add(new OpportunityContactRole(
                    OpportunityId = oppId,
                    ContactId = contactId,
                    Role = desiredRoles.get(contactId),
                    IsPrimary = (contactId == donor.Id)
                ));
            }
        }

        if (!toDelete.isEmpty()) {
            delete toDelete;
        }
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }
}
