/**
 * Links parent contacts to child contacts as NPSP Relationships.
 *
 * NPSP (List Setting reciprocal method) automatically creates the reciprocal
 * relationship (Son / Daughter / Child, based on the lookup configuration) when a
 * Relationship record is inserted. So this class inserts only the forward record
 * (child -> parent, type 'Parent'). Inserting the reciprocal here as well would
 * create duplicate records.
 *
 * Bulk and governor-limit profile for a single call:
 *   - At most 1 SOQL query (existing relationships in either direction).
 *   - At most 1 DML statement (insert of new forward relationships).
 */
public with sharing class FamilyService {

    private static final String REL_TYPE_PARENT = 'Parent';
    private static final String REL_STATUS_CURRENT = 'Current';

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Build the candidate pairs, dropping nulls and self-links.
        List<Id> candidateChildIds = new List<Id>();
        List<Id> candidateParentIds = new List<Id>();
        Set<Id> childIdSet = new Set<Id>();
        Set<Id> parentIdSet = new Set<Id>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            candidateChildIds.add(childId);
            candidateParentIds.add(parentId);
            childIdSet.add(childId);
            parentIdSet.add(parentId);
        }

        if (candidateChildIds.isEmpty()) {
            return;
        }

        // Single SOQL: any relationship between these children and parents, in either direction.
        Set<String> existingPairKeys = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE (npe4__Contact__c IN :childIdSet AND npe4__RelatedContact__c IN :parentIdSet)
               OR (npe4__Contact__c IN :parentIdSet AND npe4__RelatedContact__c IN :childIdSet)
        ]) {
            existingPairKeys.add(pairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
            existingPairKeys.add(pairKey(rel.npe4__RelatedContact__c, rel.npe4__Contact__c));
        }

        // Build new forward relationships, skipping any pair already linked in either direction.
        // Keys are added as we go so the same pair cannot be inserted twice in one call
        // (e.g. A->B and B->A both supplied).
        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        for (Integer i = 0; i < candidateChildIds.size(); i++) {
            Id childId = candidateChildIds[i];
            Id parentId = candidateParentIds[i];

            String forwardKey = pairKey(childId, parentId);
            String reverseKey = pairKey(parentId, childId);
            if (existingPairKeys.contains(forwardKey) || existingPairKeys.contains(reverseKey)) {
                continue;
            }

            existingPairKeys.add(forwardKey);
            existingPairKeys.add(reverseKey);

            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = REL_TYPE_PARENT,
                npe4__Status__c = REL_STATUS_CURRENT
            ));
        }

        // Single DML statement.
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    private static String pairKey(Id fromId, Id toId) {
        return String.valueOf(fromId) + ':' + String.valueOf(toId);
    }
}
