```apex
/**
 * TDTM handler: creates a "Major gift thank-you call" Task when an Opportunity
 * becomes a qualifying major gift (Closed Won and Amount >= 5000).
 *
 * Registered via an NPSP Trigger Handler record:
 *   Class: OPP_MajorGiftFollowUp_TDTM, Object: Opportunity,
 *   Trigger Action: AfterInsert;AfterUpdate, Load Order: 5, Asynchronous: false
 *
 * Bulk design:
 *   - 0 SOQL queries. Every field needed (StageName, Amount, CloseDate, OwnerId,
 *     npsp__Primary_Contact__c) is already present on the trigger records.
 *   - Tasks are collected in memory and returned in a single DmlWrapper, which the
 *     NPSP TDTM dispatcher commits in one DML statement for the whole batch.
 */
public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final String CLOSED_WON_STAGE = 'Closed Won';
    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;
    private static final Integer FOLLOW_UP_DAYS = 3;
    private static final String TASK_SUBJECT = 'Major gift thank-you call';

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        // Only act on after-insert / after-update contexts.
        Boolean isInsert = (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert);
        Boolean isUpdate = (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate);
        if (!isInsert && !isUpdate) {
            return dmlWrapper;
        }

        // Index prior versions by Id so update comparisons do not depend on list ordering.
        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>();
        if (isUpdate && oldlist != null) {
            for (SObject oldRecord : oldlist) {
                oldById.put(oldRecord.Id, (Opportunity) oldRecord);
            }
        }

        List<Task> tasksToInsert = new List<Task>();

        for (SObject sobj : newlist) {
            Opportunity newOpp = (Opportunity) sobj;

            if (!isQualifyingNow(newOpp)) {
                continue;
            }

            if (isInsert) {
                tasksToInsert.add(buildTask(newOpp));
                continue;
            }

            // AfterUpdate: only create a task on the transition into a qualifying state.
            Opportunity oldOpp = oldById.get(newOpp.Id);
            Boolean wasQualifying = (oldOpp != null) && isQualifying(oldOpp);
            if (!wasQualifying) {
                tasksToInsert.add(buildTask(newOpp));
            }
        }

        if (!tasksToInsert.isEmpty()) {
            dmlWrapper.objectsToInsert.addAll(tasksToInsert);
        }

        return dmlWrapper;
    }

    /** True when the Opportunity currently meets the major-gift criteria. */
    private static Boolean isQualifyingNow(Opportunity opp) {
        return isQualifying(opp);
    }

    /** Closed Won with Amount >= threshold. Null Amount never qualifies. */
    private static Boolean isQualifying(Opportunity opp) {
        return opp.StageName == CLOSED_WON_STAGE
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_THRESHOLD;
    }

    private static Task buildTask(Opportunity opp) {
        Date activityDate = (opp.CloseDate != null)
            ? opp.CloseDate.addDays(FOLLOW_UP_DAYS)
            : null;

        return new Task(
            Subject = TASK_SUBJECT,
            Priority = 'High',
            Status = 'Not Started',
            WhatId = opp.Id,
            WhoId = opp.npsp__Primary_Contact__c,
            OwnerId = opp.OwnerId,
            ActivityDate = activityDate
        );
    }
}
