```apex
/**
 * Filters a set of record Ids down to those the running user can edit.
 *
 * Edit access is read from the UserRecordAccess object, which already accounts for
 * object permissions, ownership, sharing rules, the role hierarchy, View All / Modify All,
 * and manual shares. The class does not re-implement any of those rules.
 *
 * Bulk notes: IDs are queried in chunks of CHUNK_SIZE, so a call with 2,000 IDs uses
 * 10 SOQL queries (limit is 20 per transaction). Each chunk is a single query.
 */
public with sharing class RecordAccessService {

    private static final Integer CHUNK_SIZE = 200;

    /**
     * Returns the subset of recordIds the running user has edit access to.
     * Null or empty input returns an empty set. Null elements are ignored.
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> result = new Set<Id>();
        if (recordIds == null || recordIds.isEmpty()) {
            return result;
        }

        List<Id> ids = new List<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                ids.add(recordId);
            }
        }
        if (ids.isEmpty()) {
            return result;
        }

        Id currentUserId = UserInfo.getUserId();

        for (Integer start = 0; start < ids.size(); start += CHUNK_SIZE) {
            Integer finish = Math.min(start + CHUNK_SIZE, ids.size());
            List<Id> chunk = new List<Id>();
            for (Integer i = start; i < finish; i++) {
                chunk.add(ids[i]);
            }

            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :currentUserId
                  AND RecordId IN :chunk
            ]) {
                if (access.HasEditAccess) {
                    result.add(access.RecordId);
                }
            }
        }

        return result;
    }
}
