```apex
public with sharing class EmployeeDirectoryService {

    private static final String OBJECT_API_NAME = 'FB_Employee__c';
    private static final List<String> OPTIONAL_FIELDS = new List<String>{
        'Department__c',
        'Salary__c',
        'Personal_Email__c'
    };

    /**
     * Returns the FB_Employee__c records visible to the running user (sharing enforced),
     * ordered by Name ascending. Only the fields the running user can read are included
     * in the query, so unreadable fields are absent from the returned records rather than
     * null. Returns an empty list if the user cannot read the object.
     */
    public static List<FB_Employee__c> getDirectory() {
        Schema.DescribeSObjectResult objectDescribe = Schema.FB_Employee__c.SObjectType.getDescribe();
        if (!objectDescribe.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        Map<String, Schema.SObjectField> fieldMap = objectDescribe.fields.getMap();

        List<String> selectFields = new List<String>{ 'Id', 'Name' };
        for (String fieldName : OPTIONAL_FIELDS) {
            Schema.SObjectField sObjectField = fieldMap.get(fieldName.toLowerCase());
            if (sObjectField != null && sObjectField.getDescribe().isAccessible()) {
                selectFields.add(fieldName);
            }
        }

        String soql = 'SELECT ' + String.join(selectFields, ', ')
            + ' FROM ' + OBJECT_API_NAME
            + ' ORDER BY Name ASC'
            + ' WITH USER_MODE';

        return (List<FB_Employee__c>) Database.query(soql);
    }
}
