```apex
/**
 * Moves ownership of the given Accounts and all of their Contacts to a new owner.
 *
 * Trigger Actions Framework (0.3.4) usage:
 * - All Account trigger actions are bypassed for the duration of this method. The bypass is
 *   applied only if it is not already active, and it is cleared in a finally block only if this
 *   method set it, so a caller's existing Account bypass is left untouched.
 * - Contact trigger actions are not bypassed and run normally.
 *
 * Limits: one SOQL query (Contacts) and two DML statements (Accounts, then Contacts),
 * regardless of the number of Accounts. Account records are built from the Ids directly,
 * so no Account query is needed.
 *
 * DML is all-or-none (the update statement) and exceptions propagate to the caller unchanged.
 */
public with sharing class AccountOwnershipService {

    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Schema.SObjectType accountType = Account.SObjectType;
        Boolean bypassSetHere = !TriggerBase.isBypassed(accountType);
        if (bypassSetHere) {
            TriggerBase.bypass(accountType);
        }

        try {
            List<Account> accountsToUpdate = new List<Account>();
            for (Id accountId : accountIds) {
                accountsToUpdate.add(new Account(Id = accountId, OwnerId = newOwnerId));
            }

            List<Contact> contactsToUpdate = new List<Contact>();
            for (Contact con : [
                SELECT Id
                FROM Contact
                WHERE AccountId IN :accountIds
            ]) {
                contactsToUpdate.add(new Contact(Id = con.Id, OwnerId = newOwnerId));
            }

            update accountsToUpdate;
            update contactsToUpdate;
        } finally {
            if (bypassSetHere) {
                TriggerBase.clearBypass(accountType);
            }
        }
    }
}
