```apex
/**
 * Trigger Action (Trigger Actions Framework 0.3.4) that prevents two Contacts on the same
 * Account from sharing an email address (case-insensitive).
 *
 * Registered via Trigger_Action__mdt for Contact, before insert and before update.
 *
 * Behaviour:
 *  - Contacts without an AccountId or Email are not checked.
 *  - On update, only records whose Email or AccountId changed are checked. Unchanged
 *    records still occupy their (account, email) slot so that a changed record cannot
 *    collide with them, but they are never rejected themselves (legacy duplicates do not
 *    block unrelated edits).
 *  - Within one save, the first record in the list that claims an (account, email) pair
 *    is accepted; every later conflicting record is rejected.
 *  - A record never conflicts with itself, and records in the current save are never
 *    compared against their stored database values (their new in-memory values are used).
 *  - Errors are added per record (addError), so valid records in the same save are unaffected.
 *  - Bulk safe: at most one SOQL query per execution, and none when nothing needs checking.
 *
 * Declared "without sharing" so the rule is enforced regardless of the running user's
 * record visibility; otherwise a user unable to see a sibling contact could create a duplicate.
 */
public without sharing class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    @TestVisible
    private static final String DUPLICATE_EMAIL_MESSAGE =
        'Another contact on this account already uses this email address.';

    /** Marks an occupant that is a stored database row rather than a record in this save. */
    private static final Integer STORED_OWNER = -1;

    public void beforeInsert(List<SObject> triggerNew) {
        validate(triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, SObject> oldById = new Map<Id, SObject>(triggerOld);
        validate(triggerNew, oldById);
    }

    private static void validate(List<SObject> triggerNew, Map<Id, SObject> oldById) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        // Partition the records: those that must be checked, and those that only occupy a slot.
        List<Integer> checkIndexes = new List<Integer>();
        List<Integer> keeperIndexes = new List<Integer>();
        Set<Id> batchIds = new Set<Id>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Contact c = (Contact) triggerNew[i];
            if (c.Id != null) {
                batchIds.add(c.Id);
            }
            if (c.AccountId == null || String.isBlank(c.Email)) {
                continue;
            }

            Boolean mustCheck = true;
            if (oldById != null && c.Id != null && oldById.containsKey(c.Id)) {
                Contact oldC = (Contact) oldById.get(c.Id);
                mustCheck = c.Email != oldC.Email || c.AccountId != oldC.AccountId;
            }

            if (mustCheck) {
                checkIndexes.add(i);
                accountIds.add(c.AccountId);
                emails.add(c.Email.toLowerCase());
            } else {
                keeperIndexes.add(i);
            }
        }

        if (checkIndexes.isEmpty()) {
            return;
        }

        // Single SOQL query for the whole execution.
        // Rows that are part of this save are skipped: their new values come from triggerNew.
        Map<String, Integer> ownerByKey = new Map<String, Integer>();
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
            AND Email IN :emails
        ]) {
            if (batchIds.contains(existing.Id)) {
                continue;
            }
            String key = keyOf(existing.AccountId, existing.Email);
            if (key != null && !ownerByKey.containsKey(key)) {
                ownerByKey.put(key, STORED_OWNER);
            }
        }

        // Unchanged records keep their slots first, so changed records cannot take them.
        for (Integer i : keeperIndexes) {
            Contact c = (Contact) triggerNew[i];
            String key = keyOf(c.AccountId, c.Email);
            if (key != null && !ownerByKey.containsKey(key)) {
                ownerByKey.put(key, i);
            }
        }

        // Checked records in list order: first claimant wins, later ones are rejected.
        for (Integer i : checkIndexes) {
            Contact c = (Contact) triggerNew[i];
            String key = keyOf(c.AccountId, c.Email);
            if (ownerByKey.containsKey(key)) {
                c.addError(DUPLICATE_EMAIL_MESSAGE);
            } else {
                ownerByKey.put(key, i);
            }
        }
    }

    private static String keyOf(Id accountId, String email) {
        if (accountId == null || String.isBlank(email)) {
            return null;
        }
        return accountId + '|' + email.toLowerCase();
    }
