```apex
/*
 * Audit action: creates a Completed Task "Amount changed" on each Opportunity whose Amount changed.
 *
 * TA_Opportunity_RoundAmount (order 20) re-updates the same Opportunities in the same transaction,
 * which re-runs this action with the rounded values. The static set records every Opportunity Id
 * already evaluated in this transaction, so the first evaluation (the user's change) decides the
 * outcome and the re-entrant evaluation is skipped. This yields at most one task per Opportunity
 * per transaction, and no task for the rounding-only change.
 */
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {

    private static Set<Id> evaluatedIds = new Set<Id>();

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, SObject> oldById = new Map<Id, SObject>(triggerOld);
        List<Task> tasks = new List<Task>();

        for (SObject rec : triggerNew) {
            Opportunity newOpp = (Opportunity) rec;

            // Already evaluated in this transaction (including re-entrant run caused by rounding)
            if (!evaluatedIds.add(newOpp.Id)) {
                continue;
            }

            Opportunity oldOpp = (Opportunity) oldById.get(newOpp.Id);
            if (oldOpp == null) {
                continue;
            }

            if (newOpp.Amount != oldOpp.Amount) {
                tasks.add(new Task(
                    Subject = 'Amount changed',
                    WhatId = newOpp.Id,
                    Status = 'Completed'
                ));
            }
        }

        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }
}
